from datetime import datetime, time

class Notifier:
    CHANNELS = ("email", "sms", "push")

    def __init__(self, quiet_start: time = time(22, 0), quiet_end: time = time(7, 0)) -> None:
        self.quiet_start = quiet_start
        self.quiet_end = quiet_end
        self.users = {}
        self.message_history = {}

    def add_user(self, user: str) -> None:
        self.users[user] = {"email": True, "sms": False, "push": False}
        self.message_history[user] = []

    def set_channel(self, user: str, channel: str, enabled: bool) -> None:
        if channel not in self.CHANNELS:
            raise ValueError(f"Invalid channel: {channel}")
        if user not in self.users:
            self.add_user(user)
        self.users[user][channel] = enabled

    def send(self, user: str, message: str, at: datetime) -> list[str]:
        if user not in self.users:
            self.add_user(user)
        delivered_channels = []
        for channel in self.CHANNELS:
            if self.users[user][channel]:
                if channel in ("sms", "push") and self.is_quiet(at.time()):
                    continue
                delivered_channels.append(channel)
        if delivered_channels:
            self.message_history[user].append(message)
        return delivered_channels

    def is_quiet(self, current_time: time) -> bool:
        if self.quiet_start < self.quiet_end:
            return self.quiet_start <= current_time < self.quiet_end
        else:
            return self.quiet_start <= current_time or current_time < self.quiet_end

    def get_users(self) -> list[str]:
        return sorted(self.users.keys())

    def enabled_channels(self, user: str) -> list[str]:
        if user not in self.users:
            self.add_user(user)
        return [channel for channel, enabled in self.users[user].items() if enabled]

    def history(self, user: str) -> list[str]:
        if user not in self.users:
            self.add_user(user)
        return self.message_history[user]


# Example usage
if __name__ == "__main__":
    notifier = Notifier()
    notifier.add_user("user1")
    notifier.add_user("user3")
    notifier.add_user("user2")
    notifier.set_channel("user1", "sms", True)
    print(notifier.send("user1", "Hello", datetime(2024, 1, 1, 12, 0)))  # Should print ['email', 'sms']
    print(notifier.send("user1", "Hello", datetime(2024, 1, 1, 23, 0)))  # Should print ['email']
    print(notifier.get_users())  # Should print ['user1', 'user2', 'user3']
    print(notifier.enabled_channels("user1"))  # Should print ['email', 'sms']
    print(notifier.history("user1"))  # Should print ['Hello', 'Hello']
```

